package com.cloudcart.controller;
import com.cloudcart.entity.Entities.*;import com.cloudcart.repository.UserRepository;import com.cloudcart.repository.ProductRepository;import com.cloudcart.repository.OrderRepository;import com.cloudcart.security.JwtFilter;import com.cloudcart.service.CloudCartService;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.data.domain.*;import org.springframework.http.HttpStatus;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;import java.math.BigDecimal;import java.util.*;
@RestController @RequestMapping("/api") public class ApiController {private final UserRepository users;private final ProductRepository products;private final OrderRepository orders;private final CloudCartService svc;private final PasswordEncoder encoder;private final JwtFilter jwt;public ApiController(UserRepository u,ProductRepository p,OrderRepository o,CloudCartService s,PasswordEncoder e,JwtFilter j){users=u;products=p;orders=o;svc=s;encoder=e;jwt=j;}
 public record Register(@NotBlank String name,@Email @NotBlank String email,@NotBlank @Size(min=8)String password){}public record Login(@Email String email,@NotBlank String password){}public record ProductInput(@NotBlank String name,@NotNull @jakarta.validation.constraints.DecimalMin("0.01") BigDecimal price,@NotNull @Min(0) Integer stock,String description,String category,String imageUrl){}public record Qty(@Min(1)int quantity){}public record StatusInput(String status){}
 @PostMapping("/auth/register")@ResponseStatus(HttpStatus.CREATED)public Map<String,Object> register(@Valid @RequestBody Register r){if(users.findByEmail(r.email()).isPresent())throw new ResponseStatusException(HttpStatus.CONFLICT,"Email is already registered");User u=new User();u.name=r.name();u.email=r.email().toLowerCase();u.password=encoder.encode(r.password());users.save(u);return Map.of("message","Account created");}
 @PostMapping("/auth/login")public Map<String,Object> login(@Valid @RequestBody Login l){User u=users.findByEmail(l.email().toLowerCase()).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Invalid email or password"));if(!encoder.matches(l.password(),u.password))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Invalid email or password");return Map.of("token",jwt.issue(u),"user",userView(u));}private Map<String,Object> userView(User u){return Map.of("id",u.id,"name",u.name,"email",u.email,"role",u.role);}
 @GetMapping("/products")public Object list(@RequestParam(required=false)String search,@RequestParam(required=false)String category,@RequestParam(required=false)String sort,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="24")int size){List<Product> all=products.findAll();if(search!=null&&!search.isBlank())all.removeIf(p->!p.name.toLowerCase().contains(search.toLowerCase()));if(category!=null&&!category.isBlank())all.removeIf(p->p.category==null||!p.category.equalsIgnoreCase(category));if("price,asc".equals(sort))all.sort(Comparator.comparing(p->p.price));if("price,desc".equals(sort))all.sort(Comparator.comparing((Product p)->p.price).reversed());int from=Math.min(page*size,all.size()),to=Math.min(from+size,all.size());return Map.of("content",all.subList(from,to),"totalElements",all.size(),"totalPages",(int)Math.ceil((double)all.size()/size),"number",page);}
 @GetMapping("/products/{id}")public Product product(@PathVariable Long id){return products.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));}@PostMapping("/products")@ResponseStatus(HttpStatus.CREATED)public Product create(@Valid @RequestBody ProductInput x){return saveProduct(new Product(),x);}@PutMapping("/products/{id}")public Product update(@PathVariable Long id,@Valid @RequestBody ProductInput x){return saveProduct(products.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND)),x);}private Product saveProduct(Product p,ProductInput x){p.name=x.name();p.price=x.price();p.stock=x.stock();p.description=x.description();p.category=x.category();p.imageUrl=x.imageUrl();return products.save(p);}@DeleteMapping("/products/{id}")@ResponseStatus(HttpStatus.NO_CONTENT)public void delete(@PathVariable Long id){products.deleteById(id);}
 @GetMapping("/cart")public Map<String,Object> cart(java.security.Principal p){return svc.cartView(svc.cart(svc.current(p.getName())));}@PostMapping("/cart/items")public Map<String,Object> add(java.security.Principal p,@RequestBody Map<String,Integer> b){return svc.cartView(svc.add(svc.current(p.getName()),b.get("productId").longValue(),b.get("quantity")));}@PutMapping("/cart/items/{id}")public Map<String,Object> quantity(java.security.Principal p,@PathVariable Long id,@Valid @RequestBody Qty q){return svc.cartView(svc.quantity(svc.current(p.getName()),id,q.quantity()));}@DeleteMapping("/cart/items/{id}")public Map<String,Object> remove(java.security.Principal p,@PathVariable Long id){return svc.cartView(svc.remove(svc.current(p.getName()),id));}
 @PostMapping("/orders")@ResponseStatus(HttpStatus.CREATED)public Map<String,Object> place(java.security.Principal p){return svc.orderView(svc.place(svc.current(p.getName())));}@GetMapping("/orders")public List<Map<String,Object>> myOrders(java.security.Principal p){return orders.findByUserIdOrderByCreatedAtDesc(svc.current(p.getName()).id).stream().map(svc::orderView).toList();}@GetMapping("/orders/{id}")public Map<String,Object> order(java.security.Principal p,@PathVariable Long id){Order o=orders.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));if(!o.user.email.equals(p.getName())&&!"ADMIN".equals(svc.current(p.getName()).role.name()))throw new ResponseStatusException(HttpStatus.FORBIDDEN);return svc.orderView(o);}
 @GetMapping("/admin/dashboard")public Map<String,Object> dashboard(){BigDecimal rev=orders.findAll().stream().filter(o->o.status!=OrderStatus.CANCELLED).map(o->o.total).reduce(BigDecimal.ZERO,BigDecimal::add);return Map.of("totalProducts",products.count(),"totalUsers",users.count(),"totalOrders",orders.count(),"totalRevenue",rev);}@GetMapping("/admin/orders")public List<Map<String,Object>> allOrders(){return orders.findAll(Sort.by(Sort.Direction.DESC,"createdAt")).stream().map(svc::orderView).toList();}@PutMapping("/admin/orders/{id}/status")public Map<String,Object> status(@PathVariable Long id,@RequestBody StatusInput b){Order o=orders.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));try{o.status=OrderStatus.valueOf(b.status());}catch(Exception e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Unknown status");}return svc.orderView(orders.save(o));}
}
